//! ↩️ A completed replay stages its actual inverse roots under one decision and retires displaced rows through the captured mutation issuer.
use crate::{CursorRevisionAccumulator,edit_retirement::ArtifactStoreOperationRowsRetirement};
use semio_framework_os_spr::Edit;
use semio_framework_os_vcs::{ArtifactHistoryLedger,ArtifactGroupVisibility,ArtifactHistoryKey};
use semio_framework_value::{ArtifactOwnedValueRetirementFactory,ErasedSnapshotRetirement,FactoryAuthority,RetainedPublicationRoot,RetainedPublicationDecision,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetirementDemand,ValueError,ValueRefusalKind};
use semio_framework_value_persistent::list::PagedList;
use std::{mem::{ManuallyDrop,size_of},sync::Arc};
type Rows<M>=Vec<(String,PagedList<M,{usize::MAX}>)>;
/// 🧳️ Row payloads and all original backing remain owned until stage cancellation or committed-root settlement completes.
pub struct ArtifactReplayInverseSettlement<M>{rows:ManuallyDrop<Option<Rows<M>>>,factory:ManuallyDrop<Option<Arc<dyn ArtifactOwnedValueRetirementFactory<M>>>>,visibility:ManuallyDrop<Option<Arc<ArtifactGroupVisibility>>>,active:ManuallyDrop<Option<ArtifactStoreOperationRowsRetirement<M>>>,decision:Option<FactoryAuthority>,displaced:ManuallyDrop<Option<PagedList<M,{usize::MAX}>>>,staged:usize,settled:usize,ledger:Option<u64>,reinstated:Option<ArtifactHistoryKey>,original_order:Option<(usize,usize)>,order_from:usize,closing:bool}
impl<M> Default for ArtifactReplayInverseSettlement<M>{fn default()->Self{Self{rows:ManuallyDrop::new(None),factory:ManuallyDrop::new(None),visibility:ManuallyDrop::new(None),active:ManuallyDrop::new(None),decision:None,displaced:ManuallyDrop::new(None),staged:0,settled:0,ledger:None,reinstated:None,original_order:None,order_from:0,closing:false}}}
fn invalid(text:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,text)}
fn header<T>()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<T>(),depth:1,..Default::default()}}
fn admits(grant:RetainedCloneGrant,d:RetirementDemand)->bool{semio_framework_value::retained_clone::retained_clone_grant_admits(grant,d)}
fn receipt(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
impl<M> ArtifactReplayInverseSettlement<M>{
 /// 📏️ Quotes the original row vector and captured issuer/decision headers without allocating or copying any mutation.
 pub fn capture_demands()->RetirementDemand{header::<(Self,Rows<M>,Arc<dyn ArtifactOwnedValueRetirementFactory<M>>,Arc<ArtifactGroupVisibility>)>()}
 /// 🎟️ Captures the original finished result's rebased rows only after all independent currencies are admitted.
 pub fn capture(&mut self,edits:&ArtifactHistoryLedger<Edit<M>>,rows:&mut Rows<M>,factory:&Arc<dyn ArtifactOwnedValueRetirementFactory<M>>,visibility:&Arc<ArtifactGroupVisibility>,grant:RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>{self.capture_selected(edits,rows,factory,visibility,None,grant)}
 /// ↩️ A restored original history slot joins the same genuine ledger-bound inverse publication.
 pub fn capture_selected(&mut self,edits:&ArtifactHistoryLedger<Edit<M>>,rows:&mut Rows<M>,factory:&Arc<dyn ArtifactOwnedValueRetirementFactory<M>>,visibility:&Arc<ArtifactGroupVisibility>,reinstated:Option<ArtifactHistoryKey>,grant:RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>{self.capture_ordered(edits,rows,factory,visibility,reinstated,None,grant)}
 pub fn capture_ordered(&mut self,edits:&ArtifactHistoryLedger<Edit<M>>,rows:&mut Rows<M>,factory:&Arc<dyn ArtifactOwnedValueRetirementFactory<M>>,visibility:&Arc<ArtifactGroupVisibility>,reinstated:Option<ArtifactHistoryKey>,order:Option<&semio_framework_os_vcs::HistoryPageStack<ArtifactHistoryKey>>,grant:RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>{if reinstated.is_some_and(|key|edits.get_key(key).is_none()){return Err(invalid("inverse publication reinstated original key is absent"))}if !self.terminal_is_empty(){return Err(invalid("inverse publication already retains an original row source"))}if !visibility.pending(){return Err(invalid("inverse publication requires its original pending decision"))}let order_from=order.map(|order|order.len().checked_sub(rows.len()).ok_or_else(||invalid("inverse original order omits authored rows"))).transpose()?.unwrap_or(0);let d=Self::capture_demands();if !admits(grant,d){return Ok(Default::default())}*self.rows=Some(std::mem::take(rows));*self.factory=Some(Arc::clone(factory));*self.visibility=Some(Arc::clone(visibility));self.staged=0;self.settled=0;self.ledger=Some(edits.retained_issuance());self.reinstated=reinstated;self.original_order=order.map(|o|(o as*const _ as usize,o.len()));self.order_from=order_from;self.closing=false;Ok(receipt(d))}
 /// 👁️ Reports preparation completion without implying its original publication decision has committed.
 pub fn prepared(&self)->bool{self.rows.as_ref().is_some_and(|rows|self.staged==rows.len())&&!self.closing}
 /// 🧮️ Counts actual row roots currently owned by their original history slots.
 pub fn staged_rows(&self)->usize{self.staged-self.settled}
 /// 🫙️ Terminal ownership includes the original row vector, both issuers and every displaced row payload.
 pub fn terminal_is_empty(&self)->bool{self.rows.is_none()&&self.factory.is_none()&&self.visibility.is_none()&&self.active.is_none()&&self.decision.is_none()&&self.displaced.is_none()&&self.ledger.is_none()&&self.original_order.is_none()}
 fn key<M2>(&self,edits:&ArtifactHistoryLedger<Edit<M2>>,revision:&CursorRevisionAccumulator,id:&str,index:usize,order:Option<&semio_framework_os_vcs::HistoryPageStack<ArtifactHistoryKey>>)->Result<ArtifactHistoryKey,ValueError>{if self.original_order!=order.map(|o|(o as*const _ as usize,o.len())){return Err(invalid("inverse changed its original selected key source"))}if let Some(order)=order{let key=*order.get(self.order_from+index).ok_or_else(||invalid("inverse original selected key is absent"))?;if edits.get_key(key).is_none_or(|edit|edit.id!=id){return Err(invalid("inverse original selected edit changed"))}return Ok(key)}if let Some(key)=self.reinstated{if edits.get_key(key).is_some_and(|edit|edit.id==id){return Ok(key)}}let digest=CursorRevisionAccumulator::hash_record(b"edit-id",&[id.as_bytes()]);let position=revision.indexed_edits.get(&digest).ok_or_else(||invalid("inverse publication original edit index is absent"))?.0;let key=revision.applied.get(position).and_then(|record|record.ledger_key).ok_or_else(||invalid("inverse publication original ledger key is absent"))?;if edits.get_key(key).is_none_or(|edit|edit.id!=id){return Err(invalid("inverse publication original ledger key changed"))}Ok(key)}
 /// 📏️ Prices exactly one actual staged inverse and its original decision alias.
 pub fn preparation_demands(&self)->RetirementDemand{if self.prepared(){return Default::default()}let mut d=RetainedPublicationRoot::<PagedList<M,{usize::MAX}>>::stage_demands();d.copy_bytes+=size_of::<usize>()+size_of::<Arc<dyn RetainedPublicationDecision>>();d}
 /// 🪟️ Readers keep the original inverse until the common publisher commits its authenticated decision.
 pub fn prepare_next(&mut self,edits:&mut ArtifactHistoryLedger<Edit<M>>,revision:&CursorRevisionAccumulator,grant:RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>{self.prepare_next_in_order(edits,revision,None,grant)}
 pub fn prepare_next_in_order(&mut self,edits:&mut ArtifactHistoryLedger<Edit<M>>,revision:&CursorRevisionAccumulator,order:Option<&semio_framework_os_vcs::HistoryPageStack<ArtifactHistoryKey>>,grant:RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>{if self.ledger!=Some(edits.retained_issuance()){return Err(invalid("inverse publication requires its original ledger issuer"))}if self.closing{return Err(invalid("closing inverse publication cannot resume staging"))}if self.prepared(){return Ok(Default::default())}let d=self.preparation_demands();if !admits(grant,d){return Ok(Default::default())}let rows=self.rows.as_ref().ok_or_else(||invalid("inverse publication original rows are absent"))?;let index=rows.len()-1-self.staged;let key=self.key(edits,revision,&rows[index].0,index,order)?;let original=self.visibility.as_ref().ok_or_else(||invalid("inverse publication original decision is absent"))?;if !original.pending(){return Err(invalid("inverse publication original decision is no longer pending"))}let edit=edits.get_key_mut(key).ok_or_else(||invalid("inverse publication original mutable edit is absent"))?;if !edit.inverse.accepts_candidate(){return Err(invalid("inverse publication slot retains an original reader or candidate"))}let mut candidate=Some(std::mem::take(&mut self.rows.as_mut().unwrap()[index].1));let mut view:Option<Arc<dyn RetainedPublicationDecision>>=Some(Arc::clone(original)as Arc<dyn RetainedPublicationDecision>);let child=RetainedCloneGrant{maximum_copy_bytes:grant.maximum_copy_bytes-size_of::<usize>()-size_of::<Arc<dyn RetainedPublicationDecision>>(),..grant};let progress=match edit.inverse.stage(&mut candidate,&mut view,child){Ok(progress)=>progress,Err(error)=>{if let Some(candidate)=candidate.take(){self.rows.as_mut().unwrap()[index].1=candidate;}return Err(error)}};if candidate.is_some()||view.is_some(){return Err(invalid("admitted inverse publication failed to transfer its exact original roots"))}self.staged+=1;Ok(RetainedCloneProgress{copied_bytes:d.copy_bytes,..progress})}
 /// 🛑️ Cancellation changes only intent; the defining publisher must abort its original common decision before settlement.
 pub fn begin_close(&mut self){self.closing=true;}
}
impl<M:Send+'static> ArtifactReplayInverseSettlement<M>{
 /// 📏️ Quotes one displaced-owner close, exact root settlement, original row move or final vector release.
 pub fn close_demands(&self,edits:&ArtifactHistoryLedger<Edit<M>>,revision:&CursorRevisionAccumulator,body:usize)->Result<RetirementDemand,ValueError>{self.close_demands_in_order(edits,revision,None,body)}
 pub fn close_demands_in_order(&self,edits:&ArtifactHistoryLedger<Edit<M>>,revision:&CursorRevisionAccumulator,order:Option<&semio_framework_os_vcs::HistoryPageStack<ArtifactHistoryKey>>,body:usize)->Result<RetirementDemand,ValueError>{if let Some(active)=self.active.as_ref(){return if active.terminal_is_empty(){Ok(header::<Option<ArtifactStoreOperationRowsRetirement<M>>>())}else{let mut d=active.demands(body)?;d.depth=d.depth.checked_add(1).ok_or_else(||invalid("inverse child depth overflow"))?;Ok(d)}}if let Some(decision)=self.decision.as_ref(){return if decision.terminal_is_empty(){Ok(header::<Option<FactoryAuthority>>())}else{let mut d=decision.demands(body)?;d.depth=d.depth.checked_add(1).ok_or_else(||invalid("inverse issuer depth overflow"))?;Ok(d)}}if self.displaced.is_some(){return Ok(header::<(ArtifactStoreOperationRowsRetirement<M>,PagedList<M,{usize::MAX}>,Arc<dyn ArtifactOwnedValueRetirementFactory<M>>)>() )}if self.settled<self.staged{let rows=self.rows.as_ref().unwrap();let index=rows.len()-1-self.settled;let key=self.key(edits,revision,&rows[index].0,index,order)?;let mut d=edits.get_key(key).unwrap().inverse.settlement_demands();d.copy_bytes+=size_of::<usize>();return Ok(d)}if let Some(rows)=self.rows.as_ref(){if !rows.is_empty(){return Ok(header::<(ArtifactStoreOperationRowsRetirement<M>,String,PagedList<M,{usize::MAX}>,Arc<dyn ArtifactOwnedValueRetirementFactory<M>>)>() )}return Ok(RetirementDemand{copy_bytes:size_of::<Rows<M>>(),release_bytes:rows.capacity()*size_of::<(String,PagedList<M,{usize::MAX}>)>(),depth:1,..Default::default()})}if self.visibility.is_some()||self.factory.is_some(){return Ok(header::<FactoryAuthority>())}if self.ledger.is_some(){return Ok(header::<(Option<u64>,Option<(usize,usize)>)>())}Ok(Default::default())}
 /// ♻️ Returns every candidate root under the same decision and retires mutations through the captured original factory.
 pub fn close_next(&mut self,edits:&mut ArtifactHistoryLedger<Edit<M>>,revision:&CursorRevisionAccumulator,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{self.close_next_in_order(edits,revision,None,grant)}
 pub fn close_next_in_order(&mut self,edits:&mut ArtifactHistoryLedger<Edit<M>>,revision:&CursorRevisionAccumulator,order:Option<&semio_framework_os_vcs::HistoryPageStack<ArtifactHistoryKey>>,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if self.ledger.is_some_and(|original|original!=edits.retained_issuance()){return Err(invalid("inverse settlement requires its original ledger issuer"))}self.begin_close();if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}let d=self.close_demands_in_order(edits,revision,order,grant.maximum_copy_bytes)?;if !admits(grant,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if let Some(active)=self.active.as_mut(){if !active.terminal_is_empty(){return active.close_step(RetainedCloneGrant{maximum_depth:grant.maximum_depth-1,..grant}).map(|step|RetainedCloneStep::Progress(step.progress()))}self.active.take();return Ok(RetainedCloneStep::Progress(receipt(d)))}if let Some(decision)=self.decision.as_mut(){if !decision.terminal_is_empty(){return decision.step(RetainedCloneGrant{maximum_depth:grant.maximum_depth-1,..grant}).map(|step|RetainedCloneStep::Progress(step.progress()))}self.decision=None;return Ok(RetainedCloneStep::Progress(receipt(d)))}if let Some(displaced)=self.displaced.take(){*self.active=Some(ArtifactStoreOperationRowsRetirement::new(displaced,Arc::clone(self.factory.as_ref().unwrap())));return Ok(RetainedCloneStep::Progress(receipt(d)))}if self.settled<self.staged{let view=self.visibility.as_ref().unwrap();if view.pending(){return Ok(RetainedCloneStep::Progress(Default::default()))}let rows=self.rows.as_ref().unwrap();let index=rows.len()-1-self.settled;let key=self.key(edits,revision,&rows[index].0,index,order)?;if edits.get_key(key).unwrap().inverse.decision_identity()!=Some(Arc::as_ptr(view)as usize){return Err(invalid("inverse settlement changed its original decision issuer"))}let child=RetainedCloneGrant{maximum_copy_bytes:grant.maximum_copy_bytes-size_of::<usize>(),..grant};let p=edits.get_key_mut(key).unwrap().inverse.settle(&mut self.displaced,&mut self.decision,child)?;if self.displaced.is_none()||self.decision.is_none(){return Err(invalid("admitted inverse settlement omitted original displaced root or decision issuer"))}self.settled+=1;return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_bytes:d.copy_bytes,..p}))}if let Some(rows)=self.rows.as_mut(){if let Some((id,inverse))=rows.pop(){*self.active=Some(ArtifactStoreOperationRowsRetirement::new(inverse,Arc::clone(self.factory.as_ref().unwrap())).with_identity(id));}else{drop(self.rows.take());}return Ok(RetainedCloneStep::Progress(receipt(d)))}if let Some(view)=self.visibility.take(){self.decision=Some((view as Arc<dyn RetainedPublicationDecision>).into_retirement());}else if let Some(factory)=self.factory.take(){self.decision=Some(FactoryAuthority::new(factory));}else{self.ledger=None;self.original_order=None;}Ok(RetainedCloneStep::Progress(receipt(d)))}
}
impl<M> Drop for ArtifactReplayInverseSettlement<M>{fn drop(&mut self){assert!(self.terminal_is_empty()||std::thread::panicking(),"inverse publication dropped before original staged roots and mutation issuers closed");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.rows);ManuallyDrop::drop(&mut self.factory);ManuallyDrop::drop(&mut self.visibility);ManuallyDrop::drop(&mut self.active);ManuallyDrop::drop(&mut self.displaced);}}}}

